patch:
diff --git a/repro/no-var-20209.js b/repro/no-var-20209.js
new file mode 100644
index 0000000..1ef9dbb
--- /dev/null
+++ b/repro/no-var-20209.js
@@ -0,0 +1,80 @@
+"use strict";
+
+/*
+ * Repro: no-var autofix turns `var` into `let` while the variable is still
+ * read before its declaration runs, so the fixed code throws a TDZ
+ * ReferenceError.
+ *
+ * Every case is linted with only `no-var` on, autofixed, and then run.
+ * Run from repo root: node repro/no-var-20209.js
+ * Exits 1 if any autofixed output throws.
+ */
+
+const { Linter } = require("../lib/api");
+const linter = new Linter({ configType: "flat" });
+
+const cases = [
+	{
+		name: "issue snippet: read before `var o;` in the same function",
+		sourceType: "module",
+		code: "export function a() {\n    console.log(o);\n    var o;\n    return o;\n}\n",
+	},
+	{
+		name: "read through a hoisted function, called directly before the var",
+		code: "function a() {\n    g();\n    var o;\n    function g() { return o; }\n    return o;\n}\n",
+	},
+	{
+		name: "read through a hoisted function called by another hoisted function",
+		code: "function a() {\n    h();\n    var o;\n    function h() { return g(); }\n    function g() { return o; }\n    return o;\n}\n",
+	},
+	{
+		name: "read through a hoisted function invoked as g.call(...)",
+		code: "function a() {\n    g.call(null);\n    var o;\n    function g() { return o; }\n    return o;\n}\n",
+	},
+	{
+		name: "read through a hoisted function passed as a callback",
+		code: "function a() {\n    [1].forEach(g);\n    var o;\n    function g() { return o; }\n    return o;\n}\n",
+	},
+	{
+		name: "read through a hoisted function invoked with `new`",
+		code: "function a() {\n    new G();\n    var o;\n    function G() { o; }\n    return o;\n}\n",
+	},
+	{
+		name: "read through a hoisted function invoked as a tagged template",
+		code: "function a() {\n    g``;\n    var o;\n    function g() { return o; }\n    return o;\n}\n",
+	},
+];
+
+let broken = 0;
+
+for (const { name, code, sourceType = "script" } of cases) {
+	const { output } = linter.verifyAndFix(code, {
+		languageOptions: { sourceType },
+		rules: { "no-var": "error" },
+	});
+	const fixed = output !== code;
+	let status = "no autofix applied";
+
+	if (fixed) {
+		try {
+			// eslint-disable-next-line no-new-func -- execute the fixed code to show the runtime error
+			new Function(`${output.replace(/^export /u, "")}\nreturn a();`)();
+			status = "autofixed, runs fine";
+		} catch (err) {
+			broken++;
+			status = `autofixed, THROWS ${err.name}: ${err.message}`;
+		}
+	}
+
+	console.log(`--- ${name}\n${status}`);
+	if (fixed) {
+		console.log(output);
+	}
+}
+
+if (broken) {
+	console.log(`\nBUG REPRODUCED: ${broken} of ${cases.length} cases were autofixed into code that throws.`);
+	process.exitCode = 1;
+} else {
+	console.log("\nNo broken autofix.");
+}
